import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { RootState } from './store/store';
import {
  moveEvent,
  addEvent,
  deleteEvent,
  tickClock,
  setSelectedCategory
} from './store/schedulerSlice';
import { CalendarEvent, Category, WeekDay } from './types';
import { OptimizationControls } from './components/OptimizationControls';
import { MemoizedEventCard, UnmemoizedEventCard } from './components/EventCard';
import { RenderMonitor } from './components/RenderMonitor';
import { AddEventModal } from './components/AddEventModal';

const DAYS: WeekDay[] = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
const CATEGORIES: Category[] = ['Meeting', 'Deadline', 'Focus block', 'Personal'];

export const App: React.FC = () => {
  const dispatch = useDispatch();
  const { events, selectedCategory, config } = useSelector(
    (state: RootState) => state.scheduler
  );

  const [renderCounts, setRenderCounts] = useState<Record<string, number>>({});
  const [modalOpen, setModalOpen] = useState(false);
  const [targetModalDay, setTargetModalDay] = useState<WeekDay>('Mon');

  // Clock simulation: triggers state updates every 450ms
  useEffect(() => {
    if (!config.liveClock) return;
    const timer = setInterval(() => {
      dispatch(tickClock());
    }, 450);
    return () => clearInterval(timer);
  }, [config.liveClock, dispatch]);

  const handleRecordRender = useCallback((id: string) => {
    setRenderCounts((prev) => ({
      ...prev,
      [id]: (prev[id] || 0) + 1
    }));
  }, []);

  const handleResetCounters = () => {
    setRenderCounts({});
  };

  // Drag handlers
  const stableDragStart = useCallback(
    (e: React.DragEvent, id: string) => {
      e.dataTransfer.setData('text/plain', id);
    },
    []
  );

  const unstableDragStart = (e: React.DragEvent, id: string) => {
    e.dataTransfer.setData('text/plain', id);
  };

  const activeDragStartHandler = config.useCallbackHandlers
    ? stableDragStart
    : unstableDragStart;

  const handleDrop = (e: React.DragEvent, targetDay: WeekDay) => {
    e.preventDefault();
    const id = e.dataTransfer.getData('text/plain');
    if (id) {
      dispatch(moveEvent({ id, targetDay }));
    }
  };

  // Filter calculation
  const filteredEventsMemo = useMemo(() => {
    if (selectedCategory === 'All') return events;
    return events.filter((e) => e.category === selectedCategory);
  }, [events, selectedCategory]);

  const filteredEventsUnmemo =
    selectedCategory === 'All'
      ? events
      : events.filter((e) => e.category === selectedCategory);

  const displayedEvents = config.useMemoFilter
    ? filteredEventsMemo
    : filteredEventsUnmemo;

  const CardComponent = config.useMemoCards
    ? MemoizedEventCard
    : UnmemoizedEventCard;

  const handleOpenAddModal = (day: WeekDay) => {
    setTargetModalDay(day);
    setModalOpen(true);
  };

  return (
    <div style={{ backgroundColor: '#050b18', minHeight: '100vh' }} className="p-8 text-slate-100 font-sans">
      <header className="mb-6 text-left">
        <h1 className="text-3xl font-bold tracking-tight text-white mb-2">
          Interactive Calendar
        </h1>
        <p className="text-xs text-slate-400 max-w-3xl leading-relaxed">
          Drag events between days, then flip the switches below to see, in real time, what
          React.memo, useCallback, and useMemo actually do to re-renders.
        </p>
      </header>

      {/* Switches section */}
      <OptimizationControls onResetCounters={handleResetCounters} />

      <div className="flex flex-col lg:flex-row gap-5 items-start mt-5">
        {/* Week View Section */}
        <div 
          style={{ backgroundColor: '#0b1329', borderColor: '#1e293b' }} 
          className="flex-1 border rounded-xl p-5 w-full shadow-lg"
        >
          <div className="flex flex-wrap items-center justify-between gap-4 mb-4">
            <h2 className="text-xs font-bold uppercase tracking-wider text-slate-200">
              WEEK VIEW
            </h2>

            <div className="flex items-center space-x-1.5">
              {CATEGORIES.map((cat) => (
                <button
                  key={cat}
                  onClick={() =>
                    dispatch(setSelectedCategory(selectedCategory === cat ? 'All' : cat))
                  }
                  style={{
                    backgroundColor: selectedCategory === cat ? '#2563eb' : '#131b2e',
                    borderColor: selectedCategory === cat ? '#3b82f6' : '#334155'
                  }}
                  className="px-3 py-1 rounded-full text-xs font-medium border text-slate-200 hover:text-white transition-colors"
                >
                  {cat}
                </button>
              ))}
            </div>
          </div>

          {/* 7-column calendar day grid */}
          <div 
            style={{ borderColor: '#1e293b', backgroundColor: '#070e1f' }} 
            className="grid grid-cols-7 border rounded-lg overflow-hidden"
          >
            {DAYS.map((day) => {
              const dayEvents = displayedEvents.filter((e) => e.day === day);

              return (
                <div
                  key={day}
                  onDragOver={(e) => e.preventDefault()}
                  onDrop={(e) => handleDrop(e, day)}
                  style={{ borderColor: '#1e293b' }}
                  className="min-h-[380px] border-r last:border-r-0 p-2 flex flex-col justify-between"
                >
                  <div>
                    <div className="flex justify-between items-center mb-2 px-1">
                      <span className="text-[11px] font-semibold text-slate-400">
                        {day}
                      </span>
                      <button
                        onClick={() => handleOpenAddModal(day)}
                        className="text-xs text-slate-500 hover:text-blue-400 font-bold px-1"
                        title={`Add event to ${day}`}
                      >
                        +
                      </button>
                    </div>
                    <div className="space-y-1">
                      {dayEvents.map((event) => (
                        <CardComponent
                          key={event.id}
                          event={event}
                          onDragStart={activeDragStartHandler}
                          onRenderRecord={handleRecordRender}
                          onDelete={(id) => dispatch(deleteEvent(id))}
                        />
                      ))}
                    </div>
                  </div>
                  <button
                    onClick={() => handleOpenAddModal(day)}
                    className="w-full py-1 mt-2 text-[10px] text-slate-500 hover:text-slate-300 hover:bg-[#131b2e] rounded border border-dashed border-slate-800 transition-colors"
                  >
                    + Add
                  </button>
                </div>
              );
            })}
          </div>
        </div>

        {/* Live Profiler Render Monitor */}
        <RenderMonitor events={events} renderCounts={renderCounts} />
      </div>

      {/* Interactive Add Event Modal */}
      <AddEventModal
        isOpen={modalOpen}
        defaultDay={targetModalDay}
        onClose={() => setModalOpen(false)}
        onAdd={(ev) => dispatch(addEvent(ev))}
      />
    </div>
  );
};

export default App;
